pub fn require_builtin(workflow: &str) -> Result<(), String> {
    for name in builtin_names() {
        if name == workflow {
            return Ok(());
        }
    }
    return Err(format!("{}{}", format!("{}{}", "unknown workflow '", workflow), "' (built-ins: feature-dev) — custom .at workflows are retired"));
}

pub fn flow() -> FlowSpec {
    let mut f = FlowSpec::new("feature-dev");
    for s in feature_dev_steps() {
        let step = FlowStep::new(s.step_id, s.profession);
        f.add_step(step);
    }
    return f;
}

